window.SCENARIOS = [
 {id:'idor',title:'Broken access control',tag:'CWE-639 · IDOR / BOLA',method:'GET',label:'Order ID',initial:'1002',presets:['1001','1002','9999'],context:'Simulated identity: <strong>Alice</strong><span>Own order <strong>#1001</strong></span><span>Bob’s order <strong>#1002</strong></span>',summary:'Change the order ID. Does knowing a resource identifier give Alice permission to read it?',cause:'The endpoint fetches an order by ID but never checks whether the authenticated user owns it.',vulnerable:'order = ORDERS.get(order_id)\nreturn 200, order',fixed:'order = ORDERS.get(order_id)\nif order["owner_id"] != user:\n    return 403, {"error": "Forbidden"}\nreturn 200, order',fix:'Check resource ownership using the server-verified identity on every request. Authentication alone does not authorize access.',coverage:[['SAST','Context-dependent','A generic rule may not know that the ownership check is missing.'],['DAST','Needs two accounts','A scanner needs user and resource relationships; our targeted probe checks Alice against Bob’s order.'],['SCA','Not applicable','This is an application authorization flaw, not a vulnerable dependency.']],takeaway:'A valid session proves who you are. An ownership check decides what you may access.',file:'lab/app.py · Shop.order'},
 {id:'sqli',title:'SQL injection',tag:'CWE-89 · Query construction',method:'GET',label:'Product search term',initial:"' OR 1=1 -- ",presets:['head',"' OR 1=1 -- "],context:'Database <strong>SQLite</strong><span>Public products <strong>2</strong></span><span>Hidden product <strong>1</strong></span>',summary:'Search should return only public products. Try changing the meaning of the SQL query instead of searching for a name.',cause:'The search term is concatenated into a SQL statement. Quotes and operators become SQL syntax rather than literal data.',vulnerable:'query = "SELECT id, name FROM products " + \\\n    "WHERE public = 1 AND name LIKE \'%" + term + "%\'"\nreturn db.execute(query).fetchall()',fixed:'return db.execute(\n    "SELECT id, name FROM products "\n    "WHERE public = 1 AND name LIKE ?",\n    ("%" + term + "%",)\n).fetchall()',fix:'Bind user values with database parameters. String escaping and keyword blocklists are not a substitute for parameterization.',coverage:[['SAST','Custom rule detects it','Semgrep flags query construction in vulnerable_sql.py. The rule has positive and negative fixtures.'],['DAST','Runtime evidence','The HTTP probe submits a known payload and checks for the hidden product.'],['SCA','Not applicable','An up-to-date database library does not fix unsafe application query construction.']],takeaway:'Parameters keep SQL structure separate from user-supplied values.',file:'lab/vulnerable_sql.py / lab/fixed_sql.py'},
 {id:'xss',title:'Reflected XSS',tag:'CWE-79 · Output handling',method:'GET',label:'Text reflected into the page',initial:'<img src=x onerror="alert(1)">',presets:['hello','<img src=x onerror="alert(1)">'],context:'Output context <strong>HTML text</strong><span>Input <strong>Search term</strong></span>',summary:'A page displays a search term directly inside HTML. What happens if that term contains an element with an event handler?',cause:'Untrusted text is inserted into an HTML document without encoding for its output context.',vulnerable:'return "<h1>Search results</h1><p>" + term + "</p>"',fixed:'return "<h1>Search results</h1><p>" + \\\n    html.escape(term) + "</p>"',fix:'Encode for the actual output context. HTML escaping protects this text location; JavaScript and URL contexts need their own controls. CSP adds defense in depth.',coverage:[['SAST','Depends on data flow','A suitable rule can track untrusted input to HTML output. Our SQL-only rule does not cover XSS.'],['DAST','Reflection is observable','Our HTTP probe detects raw HTML reflection. Browser execution still needs validation.'],['SCA','Not applicable','The flaw exists in output handling in our own code.']],takeaway:'Treat input as text, unless the application explicitly requires and sanitizes HTML.',file:'lab/app.py · Shop.reflection'},
 {id:'auth',title:'Forged identity',tag:'CWE-287 · Authentication',method:'GET',label:'X-User header value',initial:'bob',presets:['alice','bob','admin'],context:'Endpoint <strong>/me</strong><span>Cookie <strong>Absent</strong></span><span>Client header <strong>X-User</strong></span>',summary:'The client sends a username in a header. Can that header establish a trustworthy identity without a valid session?',cause:'The server trusts a client-controlled username. Anyone can rewrite the header and impersonate another account.',vulnerable:'return headers.get("X-User", "alice")',fixed:'token = parse_session_cookie(headers)\nverify_hmac(token, server_secret)\nverify_expiry(token)\nreturn verified_user(token)',fix:'Use a server-verified session with an expiry, reject tampering, and ignore untrusted identity headers. The local lab uses HMAC-SHA256 tokens; production needs a complete session lifecycle.',coverage:[['SAST','Trust boundary review','A code reviewer must determine whether a header comes from an authenticated trusted proxy or the browser.'],['DAST','Targeted probe detects it','Send an identity header without a session and inspect the response.'],['SCA','Not applicable','The problem is misplaced trust, not a dependency advisory.']],takeaway:'A username supplied by a browser is a claim, not proof of identity.',file:'lab/app.py · Shop.authenticate'},
 {id:'race',title:'Coupon race condition',tag:'CWE-362 · Business logic',method:'POST × 2',label:'Parallel redemption requests',initial:'2',presets:['2'],context:'Coupon <strong>WELCOME10</strong><span>Allowed uses <strong>1</strong></span><span>Discount <strong>$10</strong></span>',summary:'Two requests check the same unused coupon before either marks it as used. Can both receive the discount?',cause:'Checking coupon availability and consuming it are separate operations. Concurrent requests can both pass the check.',vulnerable:'if coupon_used:\n    return 409\n# Another request can pass here.\ncoupon_used = True\nreturn 200',fixed:'with self.lock:\n    if coupon_used:\n        return 409\n    coupon_used = True\n    return 200',fix:'Make check-and-consume atomic. This single-process lab uses a lock. Multiple application instances need a database transaction, uniqueness constraint, or conditional write.',coverage:[['SAST','Usually insufficient','A sequential code pattern does not establish the behavior of concurrent requests.'],['DAST','Needs concurrent requests','Ordinary sequential scans may miss it. This lab includes parallel HTTP probes and a deterministic race regression.'],['SCA','Not applicable','The business invariant is violated by the application workflow.']],takeaway:'A business rule must hold under concurrency, not only in a single request.',file:'lab/app.py · Shop.redeem'},
 {id:'sca',title:'Vulnerable dependency',tag:'CWE-1104 · Software composition',method:'SCA',label:'Dependency to compare',initial:'requests==2.19.1',presets:['requests==2.19.1','requests==2.34.2'],context:'Manifest <strong>Scan-only fixture</strong><span>Installed in app <strong>No</strong></span>',summary:'The shop can be correctly coded while a third-party package has known advisories. Compare two pinned versions against recorded pip-audit results.',cause:'An old dependency pin can retain known vulnerabilities even when the application’s own code has not changed.',vulnerable:'# Scan-only manifest\nrequests==2.19.1',fixed:'# Comparison manifest\nrequests==2.34.2',fix:'Check the actual advisory and affected range, upgrade to an appropriate compatible release, and test behavior. Advisory presence alone does not establish reachability or exploitability.',coverage:[['SAST','Different concern','A code-pattern rule does not replace an advisory database for dependencies.'],['DAST','Coverage depends on use','A vulnerable package can be installed without an exposed, exploitable execution path.'],['SCA','Directly applicable','pip-audit checks these version pins against the Python packaging advisory service.']],takeaway:'A dependency finding is a starting point for triage: affected version, reachable behavior, fix, and compatibility.',file:'lab/dependencies-*.txt'}
];
